/bin/bash -lc "python - <<'PY'
import sim, mujoco
s=sim.Sim(); m=s.model
for name in ['hand', 'gripper', 'panda_hand', 'tcp', 'ee', 'site']:
    try:
        sid = mujoco.mj_name2id(m, mujoco.mjtObj.mjOBJ_SITE, name)
        print('site', name, sid)
    except Exception as e:
        pass
print('sites:')
for i in range(m.nsite):
    print(i, mujoco.mj_id2name(m, mujoco.mjtObj.mjOBJ_SITE, i))
print('bodies:')
for i in range(m.nbody):
    n = mujoco.mj_id2name(m, mujoco.mjtObj.mjOBJ_BODY, i)
    if n:
        print(i, n)
PY"

